import{_ as p,W as l,s as o,u as d,I as t,ah as h,w as e,Z as i,A as n}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const x=JSON.parse('{"title":"GIT 命令“从初学到专业”完整进阶指南 | LCTT x X-CMD","titleTemplate":false,"description":"GIT 命令“从初学到专业”完整进阶指南 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"GIT 命令“从初学到专业”完整进阶指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GIT 命令“从初学到专业”完整进阶指南 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20170730 Complete Beginners to PRO guide for GIT commands","title":"GIT 命令“从初学到专业”完整进阶指南","tag":"201712"},"relativePath":"201712/20170730 Complete Beginners to PRO guide for GIT commands.md","filePath":"[post].md"}'),c={name:"201712/20170730 Complete Beginners to PRO guide for GIT commands.md"};function r(g,a,u,b,m,v){const s=l("Link");return d(),o("div",null,[a[18]||(a[18]=t("h1",{id:"git-命令-从初学到专业-完整进阶指南",tabindex:"-1"},[e("GIT 命令“从初学到专业”完整进阶指南 "),t("a",{class:"header-anchor",href:"#git-命令-从初学到专业-完整进阶指南","aria-label":"Permalink to GIT 命令“从初学到专业”完整进阶指南"},"​")],-1)),t("p",null,[a[1]||(a[1]=e("在")),i(s,{href:"http://linuxtechlab.com/install-git-linux-ubuntu-centos/"},{default:n(()=>a[0]||(a[0]=[e("之前的教程")])),_:1}),a[2]||(a[2]=e("中，我们已经学习了在机器上安装 git。本教程，我们将讨论如何使用 git，比如与 git 一起使用的各种命令。所以我们开始吧，"))]),t("ul",null,[t("li",null,[a[4]||(a[4]=e("推荐阅读：")),i(s,{href:"http://linuxtechlab.com/install-git-linux-ubuntu-centos/"},{default:n(()=>a[3]||(a[3]=[e("如何在 Linux 上安装 GIT (Ubuntu 和 CentOS)")])),_:1})])]),a[19]||(a[19]=h(`<h3 id="设置用户信息" tabindex="-1">设置用户信息 <a class="header-anchor" href="#设置用户信息" aria-label="Permalink to 设置用户信息">​</a></h3><p>这应该是安装完 git 的第一步。我们将添加用户信息 (用户名和邮箱)，所以当我们提交代码时，会产生带有用户信息的提交信息，这使得跟踪提交过程变得更容易。要添加用户信息，命令是 <code>git config</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --global user.name &quot;Daniel&quot;</span></span>
<span class="line"><span>$ git config --global user.email &quot;dan.mike@xyz.com&quot;</span></span></code></pre></div><p>添加完用户信息之后，通过运行下面命令，我们将检查这些信息是否成功更新。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --list</span></span></code></pre></div><p>我们应该能够看到输出的用户信息。</p><h3 id="git-命令" tabindex="-1">GIT 命令 <a class="header-anchor" href="#git-命令" aria-label="Permalink to GIT 命令">​</a></h3><h4 id="新建一个仓库" tabindex="-1">新建一个仓库 <a class="header-anchor" href="#新建一个仓库" aria-label="Permalink to 新建一个仓库">​</a></h4><p>为了建立一个新仓库，运行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git init</span></span></code></pre></div><h4 id="查找一个仓库" tabindex="-1">查找一个仓库 <a class="header-anchor" href="#查找一个仓库" aria-label="Permalink to 查找一个仓库">​</a></h4><p>为了查找一个仓库，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git grep &quot;repository&quot;</span></span></code></pre></div><h4 id="与远程仓库连接" tabindex="-1">与远程仓库连接 <a class="header-anchor" href="#与远程仓库连接" aria-label="Permalink to 与远程仓库连接">​</a></h4><p>为了与远程仓库连接，运行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git remote add origin remote_server</span></span></code></pre></div><p>然后检查所有配置的远程服务器，运行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git remote -v</span></span></code></pre></div><h4 id="克隆一个仓库" tabindex="-1">克隆一个仓库 <a class="header-anchor" href="#克隆一个仓库" aria-label="Permalink to 克隆一个仓库">​</a></h4><p>为了从本地服务器克隆一个仓库，运行如下代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clone repository_path</span></span></code></pre></div><p>如果我们想克隆远程服务器上的一个仓库，那克隆这个仓库的命令是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clone repository_path</span></span></code></pre></div><h4 id="在仓库中列出分支" tabindex="-1">在仓库中列出分支 <a class="header-anchor" href="#在仓库中列出分支" aria-label="Permalink to 在仓库中列出分支">​</a></h4><p>为了检查所有可用的和当前工作的分支列表，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch</span></span></code></pre></div><h4 id="创建新分支" tabindex="-1">创建新分支 <a class="header-anchor" href="#创建新分支" aria-label="Permalink to 创建新分支">​</a></h4><p>创建并使用一个新分支，命令是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git checkout -b &#39;branchname&#39;</span></span></code></pre></div><h4 id="删除一个分支" tabindex="-1">删除一个分支 <a class="header-anchor" href="#删除一个分支" aria-label="Permalink to 删除一个分支">​</a></h4><p>为了删除一个分支，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch -d &#39;branchname&#39;</span></span></code></pre></div><p>为了删除远程仓库的一个分支，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push origin:&#39;branchname&#39;</span></span></code></pre></div><h4 id="切换到另一个分支" tabindex="-1">切换到另一个分支 <a class="header-anchor" href="#切换到另一个分支" aria-label="Permalink to 切换到另一个分支">​</a></h4><p>从当前分支切换到另一个分支，使用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git checkout &#39;branchname&#39;</span></span></code></pre></div><h4 id="添加文件" tabindex="-1">添加文件 <a class="header-anchor" href="#添加文件" aria-label="Permalink to 添加文件">​</a></h4><p>添加文件到仓库，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git add filename</span></span></code></pre></div><h4 id="文件状态" tabindex="-1">文件状态 <a class="header-anchor" href="#文件状态" aria-label="Permalink to 文件状态">​</a></h4><p>检查文件状态 (那些将要提交或者添加的文件)，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git status</span></span></code></pre></div><h4 id="提交变更" tabindex="-1">提交变更 <a class="header-anchor" href="#提交变更" aria-label="Permalink to 提交变更">​</a></h4><p>在我们添加一个文件或者对一个文件作出变更之后，我们通过运行下面命令来提交代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git commit -a</span></span></code></pre></div><p>提交变更到 head 但不提交到远程仓库，命令是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git commit -m &quot;message&quot;</span></span></code></pre></div><h4 id="推送变更" tabindex="-1">推送变更 <a class="header-anchor" href="#推送变更" aria-label="Permalink to 推送变更">​</a></h4><p>推送对该仓库 master 分支所做的变更，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push origin master</span></span></code></pre></div><h4 id="推送分支到仓库" tabindex="-1">推送分支到仓库 <a class="header-anchor" href="#推送分支到仓库" aria-label="Permalink to 推送分支到仓库">​</a></h4><p>推送对单一分支做出的变更到远程仓库，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push origin &#39;branchname&#39;</span></span></code></pre></div><p>推送所有分支到远程仓库，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push -all origin</span></span></code></pre></div><h4 id="合并两个分支" tabindex="-1">合并两个分支 <a class="header-anchor" href="#合并两个分支" aria-label="Permalink to 合并两个分支">​</a></h4><p>合并另一个分支到当前活动分支，使用命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git merge &#39;branchname&#39;</span></span></code></pre></div><h4 id="从远端服务器合并到本地服务器" tabindex="-1">从远端服务器合并到本地服务器 <a class="header-anchor" href="#从远端服务器合并到本地服务器" aria-label="Permalink to 从远端服务器合并到本地服务器">​</a></h4><p>从远端服务器下载/拉取变更到到本地服务器的工作目录，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git pull</span></span></code></pre></div><h4 id="检查合并冲突" tabindex="-1">检查合并冲突 <a class="header-anchor" href="#检查合并冲突" aria-label="Permalink to 检查合并冲突">​</a></h4><p>查看对库文件的合并冲突，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git diff -base &#39;filename&#39;</span></span></code></pre></div><p>查看所有冲突，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git diff</span></span></code></pre></div><p>如果我们在合并之前想预览所有变更，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git diff &#39;source-branch&#39; &#39;target-branch&#39;</span></span></code></pre></div><h4 id="创建标记" tabindex="-1">创建标记 <a class="header-anchor" href="#创建标记" aria-label="Permalink to 创建标记">​</a></h4><p>创建标记来标志任一重要的变更，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git tag &#39;tag number&#39; &#39;commit id&#39;</span></span></code></pre></div><p>通过运行以下命令，我们可以查找 commit id ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log</span></span></code></pre></div><h4 id="推送标记" tabindex="-1">推送标记 <a class="header-anchor" href="#推送标记" aria-label="Permalink to 推送标记">​</a></h4><p>推送所有创建的标记到远端服务器，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git push -tags origin</span></span></code></pre></div><h4 id="回复做出的变更" tabindex="-1">回复做出的变更 <a class="header-anchor" href="#回复做出的变更" aria-label="Permalink to 回复做出的变更">​</a></h4><p>如果我们想用 head 中最后一次变更来替换对当前工作树的变更，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git checkout -&#39;filename&#39;</span></span></code></pre></div><p>我们也可以从远端服务器获取最新的历史，并且将它指向本地仓库的 master 分支,而不是丢弃掉所有本地所做所有变更。为了这么做，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git fetch origin</span></span>
<span class="line"><span>$ git reset -hard master</span></span></code></pre></div><p>好了，伙计们。这些就是我们使用 git 服务器的命令。我们将会很快为大家带来更有趣的教程。如果你希望我们对某个特定话题写一个教程，请通过下面的评论箱告诉我们。像往常一样， 欢迎您的各种意见和建议。</p><hr>`,84)),t("p",null,[a[6]||(a[6]=e("via: ")),i(s,{href:"http://linuxtechlab.com/beginners-to-pro-guide-for-git-commands/"},{default:n(()=>a[5]||(a[5]=[e("http://linuxtechlab.com/beginners-to-pro-guide-for-git-commands/")])),_:1})]),t("p",null,[a[10]||(a[10]=e("作者：")),i(s,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>a[7]||(a[7]=[e("Shusain")])),_:1}),a[11]||(a[11]=e(" 译者：")),i(s,{href:"https://github.com/liuxinyu123"},{default:n(()=>a[8]||(a[8]=[e("liuxinyu123")])),_:1}),a[12]||(a[12]=e(" 校对：")),i(s,{href:"https://github.com/wxy"},{default:n(()=>a[9]||(a[9]=[e("wxy")])),_:1})]),t("p",null,[a[15]||(a[15]=e("本文由 ")),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>a[13]||(a[13]=[e("LCTT")])),_:1}),a[16]||(a[16]=e(" 原创编译，")),i(s,{href:"https://linux.cn/"},{default:n(()=>a[14]||(a[14]=[e("Linux中国")])),_:1}),a[17]||(a[17]=e(" 荣誉推出"))])])}const y=p(c,[["render",r]]);export{x as __pageData,y as default};
